const FEEMAP={NL:"EUR",DE:"EUR",FR:"EUR",BE:"EUR",IT:"EUR",ES:"EUR",FI:"EUR",IE:"EUR",LU:"EUR",US:"USD",KY:"USD",GB:"GBP",JE:"GBP",SE:"SEK",CA:"CAD",DK:"DKK",PL:"PLN",CH:"CHF",NO:"NOK"};
