 const md=d=>d.slice(5,7)+"-"+d.slice(0,4),nm=s=>s.toLowerCase().replace(/(^|[\s(-])([a-zà-ÿ])/g,(m,a,b)=>a+b.toUpperCase()).replace(/\b(Ab|Nv|Plc|Ag|Sa|Se|Asa|Spa|Bv|Kgaa|Ltd|Adr|Etf)\b/g,m=>m.length<=3||m==="Plc"?m.toUpperCase():m);
