function dcfRel(y,g1,rr,gT){let F=y,pv=0;for(let t=1;t<=10;t++){const g=t<=5?g1:g1+(gT-g1)*(t-5)/5;F*=1+g;pv+=F/Math.pow(1+rr,t)}return pv+F*(1+gT)/(rr-gT)/Math.pow(1+rr,10)}
function fairV(r){try{const D=r.D||{};if(!(r.pe>0))return null;const K=D.koers_eur,fin=r.sector==="Financieel";
 const long=Math.max(0,Math.min(25,r.eps==null?0:r.eps)),gF=typeof D.eps_fwd==="number"&&isFinite(D.eps_fwd)?Math.max(-10,Math.min(25,D.eps_fwd*100)):long*.8;
 const a=r.peh&&r.peh>0?Math.min(35,r.peh):null,b=long>=5?Math.min(35,1.5*long):null,l=[a,b].filter(x=>x!=null);
 let em=null;if(l.length){const fpe=r.pe/(1+gF/100),mid=l.reduce((t,x)=>t+x,0)/l.length;em=(mid/fpe-1)*100}
 const y=D.fcf_yield,okF=!fin&&typeof y==="number"&&isFinite(y)&&y>0.003&&y<0.25;let dc=null,sc=null,imp=null;
 if(okF){const gs=[r.fcf,r.eps,typeof D.eps_fwd==="number"?D.eps_fwd*100:null].filter(x=>x!=null&&isFinite(x)),gb=gs.length?gs.reduce((t,x)=>t+x,0)/gs.length:8,g1=Math.max(3,Math.min(22,gb*.75))/100,beta=D.beta>0?D.beta:1,rr=Math.max(.08,Math.min(.11,.04+beta*.045)),gT=.03;
  const v=(g,q)=>(dcfRel(y,g,q,gT)-1)*100;
  sc={bear:v(g1*.6,rr+.01),base:v(g1,rr),bull:v(Math.min(.25,g1*1.2),rr-.005),g1:g1*100,rr:rr*100};
  let lo=-.05,hi=.5;for(let k=0;k<40;k++){const m=(lo+hi)/2;if(dcfRel(y,m,rr,gT)<1)lo=m;else hi=m}imp=(lo+hi)/2*100;dc=sc.base}
 if(dc==null&&em==null)return null;
 const raw=dc!=null&&em!=null?.6*dc+.4*em:(dc!=null?dc:em),cp=x=>x==null?null:Math.max(-60,Math.min(60,x)),mid=cp(raw);
 const bl=x=>em!=null?.6*x+.4*em:x,lo=cp(sc?bl(sc.bear):em),hi=cp(sc?bl(sc.bull):em),zeker=dc!=null&&em!=null?(Math.abs(dc-em)<25?"Hoog":Math.abs(dc-em)<50?"Matig":"Laag"):"Laag";
 const eu=m=>K&&m!=null?K*(1+m/100):null;
 return {mid,lo:Math.min(lo,hi),hi:Math.max(lo,hi),dc,em,sc,imp,a,b,gF,zeker,fin,beperkt:Math.abs(raw)>60,eur:eu(mid),eurLo:eu(Math.min(lo,hi)),eurHi:eu(Math.max(lo,hi))}}catch(e){return null}}
function moatTab(r){const M=MOAT[r.tk],F=fairV(r);
 const mo=M?`<div class="tile" style="margin-top:12px"><div class="lbl">Moat</div><div style="display:flex;gap:8px;align-items:center;margin:4px 0"><span class="pill ${/breed/i.test(M.s)?"g":M.s==="Matig"?"n":"a"}">${M.s}</span><span>${M.m}</span></div><div class="lbl" style="margin-top:10px">Belangrijkste concurrenten</div><div>${M.c.join(", ")}</div></div>
 <div class="tile" style="margin-top:10px"><div class="lbl">Redenen om niet in dit bedrijf te zitten</div><ul>${M.b.map(t=>`<li>${t}</li>`).join("")}</ul></div>`:`<div class="note" style="margin-top:12px">Voor dit bedrijf heb ik nog geen moat-beoordeling.</div>`;
 const e0=n=>n==null?"–":(n>=0?"+":"−")+Math.round(Math.abs(n))+"%",E0=n=>n==null?"":" (€ "+Math.round(n).toLocaleString("nl-NL")+")";
 const fv=F?`<div class="tile" style="margin-top:10px"><div class="lbl">Redelijke waarde (indicatie)</div><div style="display:flex;justify-content:space-between;align-items:baseline"><b class="num ${cls(F.mid)}" style="font-size:22px">${e0(F.mid)}</b><span class="pill ${F.mid>15?"g":F.mid<-15?"a":"n"}">${F.mid>15?"onder redelijke waarde":F.mid<-15?"boven redelijke waarde":"rond redelijke waarde"}</span></div>
 ${F.eur?`<div class="note" style="margin:2px 0 6px">Ongeveer € ${Math.round(F.eur).toLocaleString("nl-NL")} per aandeel, bandbreedte € ${Math.round(F.eurLo).toLocaleString("nl-NL")} tot € ${Math.round(F.eurHi).toLocaleString("nl-NL")}. Zekerheid van het model: <b>${F.zeker}</b>.</div>`:`<div class="note" style="margin:2px 0 6px">Zekerheid van het model: <b>${F.zeker}</b>.</div>`}
 ${F.sc?`<div class="kv" style="grid-template-columns:1fr 1fr 1fr"><div><small>Pessimistisch</small><b class="num ${cls(F.sc.bear)}">${e0(F.sc.bear)}</b><small>${E0(r.D.koers_eur?r.D.koers_eur*(1+F.sc.bear/100):null)}</small></div><div><small>Basis</small><b class="num ${cls(F.sc.base)}">${e0(F.sc.base)}</b><small>${E0(r.D.koers_eur?r.D.koers_eur*(1+F.sc.base/100):null)}</small></div><div><small>Optimistisch</small><b class="num ${cls(F.sc.bull)}">${e0(F.sc.bull)}</b><small>${E0(r.D.koers_eur?r.D.koers_eur*(1+F.sc.bull/100):null)}</small></div></div>
 <div class="note" style="margin:8px 0 0"><b>Wat de koers nu al verwacht:</b> de huidige koers is alleen gerechtvaardigd als de vrije kasstroom de komende 5 jaar ${f1(F.imp)}% per jaar groeit. Mijn basisaanname is ${f1(F.sc.g1)}%. ${F.imp>F.sc.g1+4?"De markt verwacht dus meer dan ik aanneem.":F.imp<F.sc.g1-4?"De markt verwacht dus minder dan ik aanneem.":"Dat ligt dicht bij elkaar."}</div>`:""}
 <div class="note" style="margin:8px 0 0">${F.sc?`<b>Methode 1, kasstroom (60%):</b> de vrije kasstroom van nu groeit 5 jaar met ${f1(F.sc.g1)}% per jaar (het gemiddelde van je kasstroom- en winstgroei en de analistenverwachting, met een afslag van 25%), daarna vlakt het af naar 3% in jaar 10. Contant gemaakt tegen ${f1(F.sc.rr)}% (op basis van de beta). De drie scenario's hierboven zijn alleen methode 1. De bandbreedte in euro's combineert beide methodes. Pessimistisch is 40% minder groei en 1 punt hogere discontovoet, optimistisch 20% meer groei.<br>`:`<b>Kasstroom:</b> ${F.fin?"voor banken, verzekeraars en holdings is vrije kasstroom niet bruikbaar, dus alleen methode 2":"geen betrouwbare kasstroomdata, dus alleen methode 2"}.<br>`}${F.em!=null?`<b>Methode 2, winst${F.sc?" (40%)":""}:</b> winst volgend jaar × een redelijke PE, het gemiddelde van het historische PE (${F.a?f1(F.a):"n.v.t."}) en 1,5 × de winstgroei (${F.b?f1(F.b):"n.v.t."}), beide maximaal 35. Geeft ${e0(F.em)}.`:""}${F.beperkt?"<br>De uitkomst is afgekapt op ±60%. Dat zegt dat het model hier slecht past.":""}</div></div>`:`<div class="note" style="margin-top:10px">Voor dit bedrijf kan ik geen redelijke waarde berekenen (ontbrekende winstdata).</div>`;
 return mo+fv+`<div class="note" style="margin-top:10px">De moat, concurrenten en risico's zijn mijn inschatting uit algemene kennis, niet getoetst aan de nieuwste cijfers. Ze zijn bedoeld als startpunt voor je eigen onderzoek, geen advies.</div>`}

